#include "Models/Images/Jpeg.hpp"

#include <array>
#include <cassert>
#include <cstdint>
#include <string>
#include <vector>

namespace {
using Bytes = std::vector<std::uint8_t>;

Bytes fromHex(const char *text)
{
    Bytes out;
    auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    while (*text) {
        const int hi = nibble(*text++);
        if (hi < 0 || !*text) break;
        const int lo = nibble(*text++);
        assert(lo >= 0);
        out.push_back(static_cast<std::uint8_t>((hi << 4) | lo));
    }
    return out;
}

void assertNear(const std::vector<std::uint8_t>& rgba, const std::array<int,16>& expected, int tolerance)
{
    assert(rgba.size() == expected.size());
    for (std::size_t i = 0u; i < rgba.size(); ++i) {
        const int delta = static_cast<int>(rgba[i]) - expected[i];
        assert(delta >= -tolerance && delta <= tolerance);
    }
}

} // namespace

int main()
{
    const Bytes gray = fromHex(
        ""
    );
    const Bytes color = fromHex(
        ""
    );
    const Bytes progressive = fromHex(
        ""
    );

    Models::Images::Image image;
    std::string error;
    assert(Models::Images::Jpeg::matches(gray.data(), gray.size()));
    assert(Models::Images::Jpeg::decode(gray.data(), gray.size(), &image, &error));
    assert(image.width == 2 && image.height == 2 && !image.meaningful_alpha);
    assertNear(image.rgba, {0,0,0,255, 65,65,65,255, 130,130,130,255, 251,251,251,255}, 3);

    assert(Models::Images::Jpeg::decode(color.data(), color.size(), &image, &error));
    assertNear(image.rgba, {75,75,73,255, 153,153,151,255, 29,29,27,255, 254,254,252,255}, 4);

    assert(Models::Images::Jpeg::decode(progressive.data(), progressive.size(), &image, &error));
    assertNear(image.rgba, {75,75,73,255, 153,153,151,255, 29,29,27,255, 254,254,252,255}, 5);

    Bytes truncated = color;
    truncated.resize(truncated.size() - 20u);
    assert(!Models::Images::Jpeg::decode(truncated.data(), truncated.size(), &image, &error));
    assert(!error.empty());

    return 0;
}
